layer.css:
[data-ryt="footer"] { color: var(--ryt-text); border-top: 2px solid rgb(86, 96, 105); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { border-top: 1px solid var(--ryt-border); border-bottom: 1px solid var(--ryt-border); border-radius: 0px; transition: all; border-right: none; border-left: none }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 15px; font-weight: 700; font-style: normal; line-height: 1.75; letter-spacing: 1.5px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 3px; transition: all }
[data-ryt="header"] { border-bottom: 2px solid rgb(86, 96, 105); border-top: none }
[data-ryt="nav"] a { color: var(--ryt-muted); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 13px; font-weight: 600; font-style: normal; line-height: 1.75; letter-spacing: 1.3px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: 2.6px; padding-top: 4px; padding-right: 0px; padding-bottom: 4px; padding-left: 0px; transition: color 0.14s cubic-bezier(0.2, 0, 0.2, 1), text-decoration-color 0.14s cubic-bezier(0.2, 0, 0.2, 1) }
[data-ryt="button"] { color: var(--ryt-bg); background-color: var(--ryt-text); border-top: 2px solid var(--ryt-text); border-right: 2px solid var(--ryt-text); border-bottom: 2px solid var(--ryt-text); border-left: 2px solid var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 600; font-style: normal; line-height: 1.75; letter-spacing: 1.3px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: 2.6px; padding-top: 8px; padding-right: 16px; padding-bottom: 8px; padding-left: 16px; transition: background-color 0.14s cubic-bezier(0.2, 0, 0.2, 1), color 0.14s cubic-bezier(0.2, 0, 0.2, 1), border-color 0.14s cubic-bezier(0.2, 0, 0.2, 1) }
[data-ryt="review"] { color: var(--ryt-muted); font-family: var(--ryt-font-heading); font-size: 15px; font-weight: 400; font-style: normal; line-height: 1.75; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: "JetBrains Mono", ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace; font-size: 13px; font-weight: 400; font-style: normal; line-height: 1.75; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 600; font-style: normal; letter-spacing: -0.39px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 5.2px; transition: color 0.14s cubic-bezier(0.2, 0, 0.2, 1), text-decoration-color 0.14s cubic-bezier(0.2, 0, 0.2, 1) }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 26px; font-weight: 600; font-style: normal; line-height: 1.2; letter-spacing: -0.39px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: light-dark(#8a5200, #e9a93a); text-decoration-color: light-dark(#8a5200, #e9a93a); color: light-dark(#8a5200, #e9a93a) }
[data-ryt="button"]:hover { color: light-dark(#8a5200, #e9a93a); text-decoration-color: light-dark(#8a5200, #e9a93a); color: light-dark(#eff0ec, #12161a) }
[data-ryt="nav"] a:hover { color: light-dark(#8a5200, #e9a93a); text-decoration-color: light-dark(#8a5200, #e9a93a); color: light-dark(#14181c, #e4e7e9) }
